// Obtener el texto devuelto por el extractor
const textoExtractor = $('Paso 1 Analizar y Extraer Especificacion2').item.json.text || '';
const textoOriginal  = $('Extraer Variables de Entrada2').item.json.textoOriginal;
const textoCambios   = $('Extraer Variables de Entrada2').item.json.textoCambios;
const tipoCambio     = $('Extraer Variables de Entrada2').item.json.tipoCambio;

// Limpiar posibles bloques de markdown que GPT pueda agregar
let jsonLimpio = textoExtractor
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let especificacion = {};
try {
  especificacion = JSON.parse(jsonLimpio);
} catch(e) {
  // Si falla el parseo, construir especificación básica de respaldo
  especificacion = {
    seccion: 'Seccion no identificada',
    tipoOperacion: 'agregar_parrafo',
    posicion: 'Al final del documento',
    contenidoIntegrar: textoCambios.substring(0, 300),
    resumenCambio: 'Agregar informacion al documento'
  };
}

return {
  json: {
    textoOriginal,
    tipoCambio,
    especificacion,
    especificacionTexto: JSON.stringify(especificacion, null, 2)
  }
};

